[{"order":1,"type":"heading","text":"Provide and Inject for Dependency Injection in Vue.js"},{"order":2,"type":"paragraph","text":"Dependency injection in Vue.js is handled via the provide and inject APIs. Normally, data is passed down the component tree using props. However, for deeply nested components, passing props through every intermediate layer (prop drilling) becomes tedious and hard to maintain. Provide and inject allow an ancestor component to serve as a dependency provider for all its descendants, regardless of how deep the component tree goes."},{"order":3,"type":"subheading","text":"How Provide Works"},{"order":4,"type":"paragraph","text":"The provide option or the provide() composition function allows a component to declare data that it wants to expose to its descendants. In the Composition API, you use the provide function imported from vue."},{"order":5,"type":"code","text":"import { provide, ref } from 'vue';

export default {
  setup() {
    const theme = ref('dark');
    provide('themeValue', theme);
  }
};"},{"order":6,"type":"subheading","text":"How Inject Works"},{"order":7,"type":"paragraph","text":"Any descendant component can use the inject function to consume the data provided by an ancestor component. If the provided value is a ref, reactivity is preserved across the component boundary."},{"order":8,"type":"code","text":"import { inject } from 'vue';

export default {
  setup() {
    const theme = inject('themeValue');
    return { theme };
  }
};"},{"order":9,"type":"subheading","text":"Handling Missing Providers with Default Values"},{"order":10,"type":"paragraph","text":"By default, Vue assumes that the injected property is supplied by an ancestor. If no matching provide is found, Vue will throw a runtime warning. To prevent this, you can supply a default value as the second argument to inject."},{"order":11,"type":"code","text":"import { inject } from 'vue';

export default {
  setup() {
    const theme = inject('themeValue', 'light');
    return { theme };
  }
};"},{"order":12,"type":"subheading","text":"Best Practices and Reactivity"},{"order":13,"type":"bullet_point","text":"Always mutate provided reactive state inside the provider component to maintain a single source of truth."},{"order":14,"type":"bullet_point","text":"Use readonly() wrapper when providing state to prevent descendant components from mutating the provided data directly without explicit methods."},{"order":15,"type":"bullet_point","text":"Use Symbol keys instead of strings for injection keys in large applications to avoid naming collisions."}]
